package com.example.hiringsys.entity; import jakarta.persistence.*;
@Entity @Table(name="usuario") public class Usuario { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true,length=150) private String email; @Column(nullable=false,length=100) private String senha; public Long getId(){return id;} public void setId(Long v){id=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getSenha(){return senha;} public void setSenha(String v){senha=v;} }
